# Ensure the extension module is active so module.enter() has run.
_active_module_name = slicer.util.selectedModule()
if _active_module_name != 'SlicerE3Implant':
    try:
        slicer.util.selectModule('SlicerE3Implant')
    except Exception as _module_enter_error:
        print(f"Warning: could not activate module 'SlicerE3Implant': {_module_enter_error}")
# precondition:end

# Drive the extension's own widget handler on the live module widget:
# it performs the full action (reads selected nodes, creates the
# output nodes downstream steps depend on, toggles dependent UI).
_widget = None
try:
    _widget = slicer.util.getModuleWidget('SlicerE3Implant')
except Exception:
    _widget = None
if _widget is None:
    try:
        _widget = slicer.modules.slicere3implant.widgetRepresentation().self()
    except Exception:
        _widget = None
if _widget is None:
    raise RuntimeError("Could not obtain the SlicerE3Implant module widget for 'loadButton'.")
if not hasattr(_widget, 'onLoadSkull'):
    raise RuntimeError("SlicerE3Implant widget has no handler 'onLoadSkull' for 'loadButton'; regenerate the CLI.")

# Pre-select the skull segmentation (and its skull segment) in the widget's list first,
# which is the manual prerequisite of the "Load Skull Mask" button.
_skullSegmentationNode = None
_skullSegmentId = None
for _segNode in slicer.util.getNodesByClass('vtkMRMLSegmentationNode'):
    _segmentation = _segNode.GetSegmentation()
    for _segmentId in _segmentation.GetSegmentIDs():
        if 'skull' in _segmentation.GetSegment(_segmentId).GetName().lower():
            _skullSegmentationNode = _segNode
            _skullSegmentId = _segmentId
            break
    if _skullSegmentationNode is not None:
        break
if _skullSegmentationNode is None:
    raise RuntimeError("Cannot click 'Load Skull Mask': no segmentation with a skull segment was found in the scene.")

_segmentationCombo = None
for _child in _widget.findChildren('QWidget'):
    if hasattr(_child, 'currentSegmentID'):
        _segmentationCombo = _child
        break
if _segmentationCombo is None:
    raise RuntimeError("Cannot click 'Load Skull Mask': SlicerE3Implant widget has no segmentation selector to preselect.")
_segmentationCombo.setCurrentNode(_skullSegmentationNode)
_segmentationCombo.setCurrentSegmentID(_skullSegmentId)

_widget.onLoadSkull()
print("[CranialImplantPlanning] Step 'cb_step_11': clicked 'loadButton' via onLoadSkull().")
